#nullable enable
using System.Collections.Immutable;
using HourBooking.Contracts;

namespace HourBooking.Slices.Booking;

/// <summary>
/// Live aggregation over the Timesheet stream, keyed by employeeId + month. Same stream as
/// BookHoursState, and — for now — the same fold.
///
/// NOTE, because it is the second slice and this is the first time it shows: per-slice aggregates
/// DUPLICATE when two slices ask the same questions of the same stream. This type is ~40 lines that
/// differ from BookHoursState only in the questions exposed at the bottom. Four command slices write
/// the Timesheet stream, so that is four copies of one fold. Recorded in ANTI-PATTERNS.md rather
/// than resolved: for a POC the duplication is cheap and honest, and the resolution (extract the fold,
/// keep the per-slice question surface) is worth doing on real evidence rather than on two examples.
/// </summary>
public sealed record CorrectHoursState
{
    public const decimal DailyCap = 18m;

    public string Id { get; init; } = default!;
    public int Version { get; set; }

    public ImmutableDictionary<Guid, Line> Lines { get; init; } = ImmutableDictionary<Guid, Line>.Empty;

    public sealed record Line(DateOnly Date, Guid ProjectId, decimal Hours);

    public static string StreamKey(Guid employeeId, string month) => $"timesheet:{employeeId}:{month}";

    // --- what the endpoint asks it ---------------------------------------------------------------

    /// <summary>
    /// "Correcting a day+project that was never booked is not a correction." A correction names a
    /// booking, so the question is whether that booking is still standing — BookingRemoved took it
    /// out of Lines, and a removed booking cannot be corrected either.
    /// </summary>
    public Line? Find(Guid bookingId) => Lines.TryGetValue(bookingId, out var line) ? line : null;

    /// <summary>
    /// The day's hours EXCLUDING the booking being corrected, because a correction replaces that
    /// booking's hours rather than adding to them. Counting the old value would refuse a correction
    /// from 12 to 13 on an 18-hour day.
    /// </summary>
    public decimal HoursOnExcluding(DateOnly date, Guid bookingId) =>
        Lines.Where(kv => kv.Key != bookingId && kv.Value.Date == date).Sum(kv => kv.Value.Hours);

    // --- the fold --------------------------------------------------------------------------------

    public static CorrectHoursState Apply(HoursBooked e, CorrectHoursState current) =>
        current with { Lines = current.Lines.SetItem(e.BookingId, new Line(e.Date, e.ProjectId, e.Hours)) };

    /// <summary>
    /// "The truth for a day+project is the last correction, or the booking if there was none." A
    /// correction carries the new TOTAL, so it replaces rather than accumulates — and it carries no
    /// date or project, so the standing line supplies both.
    /// </summary>
    public static CorrectHoursState Apply(HoursCorrected e, CorrectHoursState current) =>
        current.Lines.TryGetValue(e.BookingId, out var line)
            ? current with { Lines = current.Lines.SetItem(e.BookingId, line with { Hours = e.Hours }) }
            : current;

    public static CorrectHoursState Apply(BookingRemoved e, CorrectHoursState current) =>
        current with { Lines = current.Lines.Remove(e.BookingId) };

    public static CorrectHoursState Apply(ZeroHoursFilled e, CorrectHoursState current) =>
        current with { Lines = current.Lines.SetItem(e.BookingId, new Line(e.Date, e.ProjectId, e.Hours)) };
}
